require_once __DIR__.'/../config/config.php';requireLogin();$pdo=db();ensureAuthSchema($pdo);if(empty($_SESSION['force_password_change'])){header('Location:index.php');exit;}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$n=(string)($_POST['new_password']??'');$c=(string)($_POST['confirm_password']??'');if(strlen($n)<8)$error='Password must be at least 8 characters.';elseif($n!==$c)$error='Passwords do not match.';elseif(password_verify($n,(string)currentUser()['password_hash']))$error='New password must be different from the temporary password.';else{$h=password_hash($n,PASSWORD_DEFAULT);$pdo->prepare("UPDATE users SET password_hash=?,must_change_password=0,remember_token_hash=NULL,remember_token_expires_at=NULL WHERE id=?")->execute([$h,(int)currentUser()['id']]);$_SESSION['user']['password_hash']=$h;unset($_SESSION['force_password_change']);clearRememberCookie();$success='Password changed successfully. Please sign in again.';}}
$bg=preg_replace('/[^a-z0-9-]/i','',strtolower(getSetting('login_background','philippine-blue')));?>
